#include "codegen_internal.h"

/**
 * @brief Write the function-qualified label for a basic block.
 *
 * @param out Target output stream.
 * @param fn_name Name of the function owning the block.
 * @param block_id ID of the block whose label is emitted.
 */
static void cg_print_block_label(FILE* out, char* fn_name, size_t block_id) {
  fprintf(out, "$%s$b%zu", fn_name, block_id);
}

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Find a single-use comparison at the branch it feeds.
IrInstruction* cg_branch_comparison(IrFunction* fn,
                                    IrBlock* block,
                                    const size_t* uses) {
  IrInstructionArray* instructions = &block->instructions;
  if (block->terminator.type != IR_TERMINATOR_CONDITIONAL ||
      instructions->count == 0)
    return NULL;

  IrOperand condition = block->terminator.value.conditional_target.condition;
  IrInstruction* last = &instructions->data[instructions->count - 1];
  if (condition.type != IR_OP_VALUE || last->result != condition.value.id ||
      uses[last->result] != 1 || cg_ordered_inclusive(fn, last))
    return NULL;

  switch (last->type) {
    case IR_INST_EQ:
    case IR_INST_NE:
    case IR_INST_LE:
    case IR_INST_GE:
      return last;
    default:
      return NULL;
  }
}

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Remove this responsibility from codegen and move it to the
