// Changes: Use the actual emitted successor for unconditional edges.
/**
 * @brief Emit a jump only when its target is valid and outside the fallthrough
 * edge.
 *
 * @param out Target output stream.
 * @param fn Function whose block label is emitted.
 * @param target Block reached by the edge.
 * @param next_block Next block in emission order, or IR_INVALID_ID.
 */
static void cg_jump_unless_next(FILE* out,
                                IrFunction* fn,
                                IrBlockId target,
                                IrBlockId next_block) {
  if (target == IR_INVALID_ID || target == next_block)
    return;

  fputs("JUMP ", out);
  cg_print_block_label(out, fn->name, target);
  cg_print_nl(out);
}

void cg_generate_block(Ctx* ctx,
                       FILE* out,
                       const CgPlacement* placement,
                       IrFunction* fn,
                       size_t block_id,
                       IrBlockId next_block,
                       IrBlock* block,
                       IrInstruction* comparison,
                       bool direct_entry) {
  fputs("LABEL ", out);
  cg_print_block_label(out, fn->name, block_id);
  cg_print_nl(out);

  for (size_t i = 0; i < block->instructions.count; i++) {
    IrInstruction* inst = &block->instructions.data[i];
    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement all"
    // Changes: Let the branch emit its own comparison.
    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement"
    // Changes: Skip a store whose result is returned directly from the stack.
    if (inst->type == IR_INST_STORE &&
        cg_stack_operand(placement, inst->operands.store.source))
      continue;

    if (inst != comparison && !cg_elides_copy(inst, placement))
      cg_generate_instruction(ctx, out, placement, fn, inst);
  }

  switch (block->terminator.type) {
    case IR_TERMINATOR_EXIT:
      fputs("EXIT ", out);
      cg_print_operand(out, placement, &block->terminator.value.exit_code);
      cg_print_nl(out);
      break;

    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement"
    // Changes: Return directly when the jump only transports a prepared stack
    // result.
    case IR_TERMINATOR_JUMP:
      if (block->instructions.count) {
        const IrInstruction* last =
            &block->instructions.data[block->instructions.count - 1];

        if (last->type == IR_INST_STORE &&
            cg_stack_operand(placement, last->operands.store.source)) {
          fputs("POPFRAME\nRETURN\n", out);
          break;
        }
      }
      // AI generated by: Codex (GPT-6.2-sol)
      // Prompt: "Remove this responsibility from codegen and move it to the
      // optimizer. Add optimalization to codegen to skip jumps if the target is
      // the following block (jumps, which will jump just one line)"
      // Changes: Share fallthrough handling with conditional edges.
      cg_jump_unless_next(out, fn, block->terminator.value.jump_target,
                          next_block);
      break;

      // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement all"
    // Changes: Exit directly from an entrypoint that has no callers.
    case IR_TERMINATOR_RETURN:
      if (direct_entry) {
        fputs("EXIT int@0\n", out);
        break;
      }

      // AI generated by: Codex (GPT-6.2-sol)
      // Prompt: "Implement all"
      // Changes: Push the return operand without a frame result variable.
      if (fn->return_type != IR_UNIT &&
          !cg_stack_operand(placement, block->terminator.value.return_value)) {
        IrFunctionId fid = (IrFunctionId)(fn - ctx->ir.functions.data);
        fputs(cg_uses_stack_return(ctx, fid) ? "PUSHS " : "MOVE LF@%ret ", out);
        cg_print_operand(out, placement, &block->terminator.value.return_value);
        cg_print_nl(out);
      }

      fputs("POPFRAME", out);
      cg_print_nl(out);
      fputs("RETURN", out);
      cg_print_nl(out);
      break;

    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement all"
    // Changes: Use the adjacent successor as fallthrough when possible.
    case IR_TERMINATOR_CONDITIONAL: {
      IrBlockId yes = block->terminator.value.conditional_target.true_target;
      IrBlockId no = block->terminator.value.conditional_target.false_target;
      // AI generated by: Codex (GPT-6.2-sol)
      // Prompt: "Remove this responsibility from codegen and move it to the
      // optimizer. Add optimalization to codegen to skip jumps if the target is
      // the following block (jumps, which will jump just one line)"
      // Changes: Use a single edge when both outcomes go to the same block. The
      // condition cannot affect control flow when both outcomes agree.
      if (yes == no) {
        cg_jump_unless_next(out, fn, yes, next_block);
        break;
      }
      // Invert the test when the true edge can use fallthrough.
      bool invert = yes == next_block;
      // AI generated by: Codex (GPT-6.2-sol)
      // Prompt: "Implement all"
      // Changes: Fuse equality branches and absorb inclusive predicate
      // inversion.

      bool unequal = invert;
      if (comparison &&
          (comparison->type == IR_INST_NE || comparison->type == IR_INST_GE ||
           comparison->type == IR_INST_LE))
        unequal = !unequal;

      bool direct = comparison && (comparison->type == IR_INST_EQ ||
                                   comparison->type == IR_INST_NE);

      if (comparison && !direct) {
        cg_print_binary_inst(out, placement,
                             comparison->type == IR_INST_GE ? "LT" : "GT",
                             comparison);
      }

      fputs(unequal ? "JUMPIFNEQ " : "JUMPIFEQ ", out);
      cg_print_block_label(out, fn->name, invert ? no : yes);
      cg_print_ws(out);

      if (direct) {
        cg_print_operand(out, placement, &comparison->operands.binary.left);
        cg_print_ws(out);
        cg_print_operand(out, placement, &comparison->operands.binary.right);
        cg_print_nl(out);
      } else {
        cg_print_operand(out, placement,
                         &block->terminator.value.conditional_target.condition);
        fputs(" bool@true\n", out);
      }
      // AI generated by: Codex (GPT-6.2-sol)
      // Prompt: "Remove this responsibility from codegen and move it to the
      // optimizer. Add optimalization to codegen to skip jumps if the target is
      // the following block (jumps, which will jump just one line)"
      // Changes: Use fallthrough for the secondary edge when adjacent.
      if (!invert)
        cg_jump_unless_next(out, fn, no, next_block);

      break;
    }
  }
}
